package com.orangemask;import org.apache.kafka.clients.consumer.ConsumerRecord;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;@Servicepublic class App{    private final JdbcTemplate jdbcTemplate;    public App(JdbcTemplate jdbcTemplate){        this.jdbcTemplate = jdbcTemplate;    }    @KafkaListener(topics = "auto-orders" , groupId = "T-DealerShip")    public void listen(String message){        String[] parts = message.split(":");        if(parts.length < 3){            return;        }        String carName = parts[0];        int carPrice = Integer.parseInt(parts[1]);        int downPaymentAmount = Integer.parseInt(parts[2]);        if (downPaymentAmount > carPrice) {            System.out.println("Rejection: the down payment exceeds the purchase price.");        } else if (downPaymentAmount == carPrice) {            System.out.println("The purchase was made without the use of credit funds.");        } else {            int creditBody = carPrice - downPaymentAmount;            double totalDebt = creditBody * 1.2;            double monthlyPayment = totalDebt / 36;            System.out.println("Monthly payment calculated: " + monthlyPayment);            jdbcTemplate.update("INSERT INTO cars(car_name, car_price, total_debt, monthly_pay) VALUES(?,?,?,?)", carName,carPrice,totalDebt,monthlyPayment);        }    }}